 max(overall_aging) as aging from snitch_db.maplemonk.product_journey group by 1 ), total_agg_sales as ( select sum(gross_sales) as total_sales, sum(clicks) as total_clicks from sales_data ), perc_data as ( SELECT a.sku_group, a.order_date, MAX(a.gross_sales) AS gross_sales, MAX(a.quantity) AS quantity, max(a.clicks) as clicks, max(customers) as customers, (SELECT total_sales FROM total_agg_sales) AS total_sales, (MAX(a.gross_sales) / (SELECT total_sales FROM total_agg_sales)) * 100 AS perc_sales, (SELECT total_clicks FROM total_agg_sales) AS total_clicks, (MAX(a.clicks) / (SELECT total_clicks FROM total_agg_sales)) * 100 AS perc_clicks FROM sales_data a GROUP BY a.sku_group, a.order_date ), cumulative_data as ( SELECT *, SUM(gross_sales) OVER (ORDER BY gross_sales DESC) AS cumulative_sales, SUM(gross_sales) OVER (ORDER BY gross_sales DESC) / total_sales * 100 AS cumulative_sales_perc, SUM(clicks) OVER (ORDER BY clicks DESC) AS cumulative_clicks, SUM(clicks) OVER (ORDER BY clicks DESC) / total_clicks * 100 AS cumulative_clicks_perc FROM perc_data ) SELECT a.sku_group, a.order_date, a.cumulative_sales_perc, a.cumulative_clicks_perc, max(a.gross_sales) as gross_sales, max(a.quantity) as quantity, MAX(b.inventory) AS inventory, max(a.customers) as customers, MAX(b.final_live_date) AS final_live_date, MAX(b.aging) AS aging, MAX(d.total_inventory) as dod_inventory, max(a.clicks) as clicks FROM cumulative_data a LEFT JOIN inv_data b ON LOWER(a.sku_group) = LOWER(b.sku_group) LEFT JOIN snitch_db.maplemonk.cut_size_analysis d ON d.date = CURRENT_DATE GROUP BY 1,2,3,4 ;",
